            let boxed = window.find("prompt-box").bounds();
            let text = editor.read(cx).text_bounds().unwrap();
            // Where the lines start, past the editor's gutter, and where they
            // wrap, short of its margin.
            let (left, right) = (
                text.left() + super::EDITOR_GUTTER,
                text.right() - super::EDITOR_WRAP_MARGIN,
            );
            assert_eq!(
                (left - boxed.left(), text.top() - boxed.top(), boxed.right() - right),
                (px(8.), px(8.), px(8.)),
                "the text's left, top, and right insets in {boxed:?}"
            );

            // The glyphs themselves: none nearer the box's edges than that,
            // less their bearings.
            let frame = crate::frame_image::Frame::of(window);
            let dark = crate::theme::palette(cx).darkest;
            let mut ink: Option<(f32, f32, f32)> = None;
            let (top, bottom) = (f32::from(boxed.top()), f32::from(boxed.top()) + 40.);
            let mut y = top + 1.;
            while y < bottom {
                let mut x = f32::from(boxed.left()) + 1.;
                while x < f32::from(boxed.right()) - 1. {
                    if frame.at(point(px(x), px(y))) != dark {
                        ink = Some(match ink {
                            None => (x, x, y),
                            Some((l, r, t)) => (l.min(x), r.max(x), t.min(y)),
                        });
                    }
                    x += 1.;
                }
                y += 1.;
            }
            let (l, r, t) = ink.expect("no text drawn");
            let (l, r, t) = (
                l - f32::from(boxed.left()),
                f32::from(boxed.right()) - r,
                t - f32::from(boxed.top()),
            );
            for (edge, inset) in [("left", l), ("right", r), ("top", t)] {
                assert!(
                    (7.0..=12.0).contains(&inset),
                    "the text is {inset} in from the box's {edge} edge"
                );
            }
        })
        .unwrap();
    }

